import ast

# Custom validation logic for NODDI (Neurite Orientation Dispersion and Density Imaging)
# Access field data with value["FieldName"]
# Raise ValidationError for failures; recommendation-level items tagged [warning]

errors = []
for i in range(len(value["DiffusionBValues"])):
    prefix = "Entry " + str(i) + ": "

    # --- Parse array-valued fields safely ---
    try:
        bvals = as_list(value["DiffusionBValues"][i])
    except Exception:
        bvals = []
        errors.append(prefix + "DiffusionBValues could not be parsed")

    try:
        dirs_per_shell = as_list(value["DirectionsPerShell"][i])
    except Exception:
        dirs_per_shell = []

    # --- Build shell -> directions mapping (by index alignment) ---
    shells = []
    for j, b in enumerate(bvals):
        n_dirs = dirs_per_shell[j] if j < len(dirs_per_shell) else None
        shells.append((b, n_dirs))

    # --- Rule 1: NumberOfDiffusionShells must be >= 2 (FAIL) ---
    try:
        if float(value["NumberOfDiffusionShells"][i]) < 2:
            errors.append(prefix + "At least two b-shells must be acquired")
    except Exception:
        errors.append(prefix + "NumberOfDiffusionShells could not be read")

    # --- Rule 2: at least 1 b-value in [500, 1000] recommended (WARNING) ---
    if len([b for b in bvals if 500 <= b <= 1000]) < 1:
        errors.append(prefix + "[warning] At least one b-value between 500 and 1000 s/mm2 is recommended for NODDI")

    # --- Rule 3: at least 1 b-value in [2000, 3000] recommended (WARNING) ---
    if len([b for b in bvals if 2000 <= b <= 3000]) < 1:
        errors.append(prefix + "[warning] At least one b-value between 2000 and 3000 s/mm2 is recommended for NODDI")

    # --- Rule 4: b-value in [500, 1000] must have >= 15 directions (FAIL), 30 preferred (WARNING) ---
    low_shell_dirs = [n for b, n in shells if 500 <= b <= 1000 and n is not None]
    if low_shell_dirs:
        total_low = sum(low_shell_dirs)
        if total_low < 15:
            errors.append(prefix + "The b-value between 500 and 1000 must have at least 15 gradient directions for NODDI")
        elif total_low < 30:
            errors.append(prefix + "[warning] The b-value between 500 and 1000 has fewer than 30 gradient directions; 30 is recommended for NODDI")

    # --- Rule 5: b-value in [2000, 3000] must have >= 15 directions (FAIL), 60 preferred (WARNING) ---
    high_shell_dirs = [n for b, n in shells if 2000 <= b <= 3000 and n is not None]
    if high_shell_dirs:
        total_high = sum(high_shell_dirs)
        if total_high < 15:
            errors.append(prefix + "The b-value between 2000 and 3000 must have at least 15 gradient directions for NODDI")
        elif total_high < 60:
            errors.append(prefix + "[warning] The b-value between 2000 and 3000 has fewer than 60 gradient directions; 60 is recommended for NODDI")

warns = [m for m in errors if "[warning]" in m]
fails = [m for m in errors if "[warning]" not in m]
if fails:
    raise ValidationError(chr(10).join("• " + m for m in fails + warns))
if warns:
    raise ValidationWarning(chr(10).join("• " + m for m in warns))
